from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Hw_info(EmssimCommand):
    def __init__(self, method="hw_info", timeout=60, rpc_connection_name='localRPC'):
        super(Hw_info, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Hw_info, self).on_new_data(**data)
        if 'msg' in data:
            if (data['msg'] == "NE reports hwConfigurationFile ready for upload"):
                self._ret['upload_file_info'] = data['transfer_info']
                self._ret['upload_file_info']['ftype'] = data['ftype']
            elif (data['msg'] == "File stored at following path"):
                if 'upload_file_info' in self._ret:
                    self._ret['upload_file_info']['path'] = data['path']
            elif (data['msg'] == "Hardware Information"):
                self._ret['hw_info'] = data['table']
        elif 'status' in data:
            self._ret['status'] = data['status']
